import cp from "node:child_process";
function main(): void {
  const child = cp.fork("/dev/null", [], { execPath: "node", silent: true });
  const channel: any = child.channel;
  const log: string[] = [];
  log.push([typeof channel.ref, typeof channel.unref, typeof channel.refCounted, typeof channel.unrefCounted].join(","));
  const results: string[] = [];
  results.push(String(channel.refCounted()), String(channel.refCounted()), String(channel.unrefCounted()), String(channel.unrefCounted()), String(channel.ref()), String(channel.unref()));
  log.push(results.join(" "));
  child.disconnect();
  child.on("exit", (code: any) => { log.push("exit " + code); console.log(log.join("|")); });
}
